// Microsoft SOC Brief 8 Oct 2026 - malicious URLs in Teams messages, QR-code-borne ones first
// MessageUrlInfo and MessageEvents columns verified against the schema pages cited beside this query.
// MC1490905 says QR code detections carry "QRCode" in a UrlLocation column of MessageUrlInfo. The schema
// page read on 8 Oct 2026 does not list that column yet, so column_ifexists keeps the query valid
// before and after the rollout reaches the tenant.
MessageUrlInfo
| where Timestamp > ago(14d)
| extend UrlLocation = column_ifexists("UrlLocation", "")
| where isnotempty(ThreatTypes) or UrlLocation =~ "QRCode"
| join kind=leftouter (
    MessageEvents
    | where Timestamp > ago(14d)
    | project TeamsMessageId, SenderEmailAddress, IsExternalThread, ThreadSubtype, DeliveryAction
  ) on TeamsMessageId
| summarize Messages = dcount(TeamsMessageId),
            Senders = make_set(SenderEmailAddress, 20),
            FirstSeen = min(Timestamp), LastSeen = max(Timestamp)
          by UrlDomain, UrlLocation, ThreatTypes, IsExternalThread
| order by UrlLocation desc, Messages desc

// Microsoft SOC Brief 28 Sep 2026 - KB5129195/KB5129194 trust-relationship fallout
// Tables and columns verified against the DeviceEvents and DeviceInfo schema pages cited beside this query.
let win = ago(14d);
let patched =
    DeviceEvents
    | where Timestamp > win
    | where ActionType == "OsVersionChanged" or AdditionalFields has_any ("5129195", "5129194")
    | summarize PatchedAt = min(Timestamp) by DeviceId, DeviceName;
DeviceInfo
| where Timestamp > win
| where isnotempty(DeviceId)
| summarize arg_max(Timestamp, JoinType, OnboardingStatus, OSPlatform, OSVersion) by DeviceId, DeviceName
| where JoinType !in ("Hybrid Azure AD joined", "Azure AD joined")
| join kind=inner patched on DeviceId
| project DeviceName, DeviceId, OSPlatform, OSVersion, JoinType, PatchedAt, SeenAt = Timestamp
| order by PatchedAt asc

// Microsoft SOC Brief 28 Sep 2026 - workload-identity shape change
// Column names verified against the AADServicePrincipalSignInLogs table reference cited beside this query.
let lookback = 30d;
let recent = 2d;
let base =
    AADServicePrincipalSignInLogs
    | where TimeGenerated between (ago(lookback) .. ago(recent))
    | summarize BaseIPs = make_set(IPAddress, 200), BaseCalls = count() by ServicePrincipalId, ServicePrincipalName;
AADServicePrincipalSignInLogs
| where TimeGenerated > ago(recent)
| summarize NowCalls = count(), NowIPs = make_set(IPAddress, 200), Resources = make_set(ResourceDisplayName, 50)
          by ServicePrincipalId, ServicePrincipalName
| join kind=leftouter base on ServicePrincipalId
| extend NewIPs = set_difference(NowIPs, coalesce(BaseIPs, dynamic([])))
| extend DailyBase = todouble(coalesce(BaseCalls, 0)) / 28.0
| where array_length(NewIPs) > 0 or NowCalls > 5 * DailyBase
| project ServicePrincipalName, ServicePrincipalId, NowCalls, DailyBase = round(DailyBase, 1),
          NewIPs, Resources
| order by NowCalls desc
